#include <stdio.h>
#include <stdint.h>
#include "joystick.h"



// This file may contain autogenerated functions... (AUTOGENERATED)


typedef struct {
    const char *name;
    int8_t x, y;
    enum joystick_direction expected;
} __joystick_test_case;

const __joystick_test_case joystick_cases[] = {
    // name               x     y    expected
    {"center",            0,    0,   NEUTRAL},
    {"inside deadzone",   29,  -29,  NEUTRAL},
    {"right",             100,  0,   RIGHT},
    {"left",             -100,  0,   LEFT},
    {"up",                0,    100, UP},
    {"down",              0,   -100, DOWN},
    {"up, slight left",  -40,   90,  UP},
    {"down, slight left",-40,  -90,  DOWN},
    {"diagonal tie",      60,   60,  RIGHT},
    {"min int8",         -128,  0,   LEFT},
    {"max int8",          127,  0,   RIGHT},
};

// Returns the number of failed tests (0 = all passed). 
int8_t joystick_run_tests(void) {
    int failed = 0;
    const int n = sizeof joystick_cases / sizeof joystick_cases[0];

    for (int i = 0; i < n; i++) {
        xy_signed in = { .x = joystick_cases[i].x, .y = joystick_cases[i].y };
        enum joystick_direction got = joystick_get_directional_basic(in);

        if (got != joystick_cases[i].expected) {
            printf("FAIL %-18s got %d, expected %d\n",
                   joystick_cases[i].name, got, joystick_cases[i].expected);
            failed++;
        }
    }

    printf("joystick: %d/%d passed\n", n - failed, n);
    return failed;
}